using Distributions
using SpecialFunctions   # for erfinv
using JSON

"""
	gen(p, sigma, name)

Generate Half-Normal quantile fixture data.

# Arguments
- `p`: probability values (0 ≤ p ≤ 1)
- `sigma`: scale parameters (σ ≥ 0)
- `name`: output filename
"""
function gen(p, sigma, name)
	z = Array{Float64}(undef, length(p))
	for i in eachindex(p)
		# Half-normal quantile:
		# Q(p) = sigma * sqrt(2) * erfinv(p)
		z[i] = sigma[i] * sqrt(2.0) * erfinv(p[i])
	end

	data = Dict(
		"p" => p,
		"sigma" => sigma,
		"expected" => z
	)

	filepath = joinpath(dir, name)
	open(filepath, "w") do f
		write(f, JSON.json(data))
		write(f, "\n")
	end
end

# Directory of this script
file = @__FILE__
dir = dirname(file)

# Generate random test values
N = 10
p = rand(N)                     # in (0,1)
sigma = rand(N) .* 5.0           # σ in [0,5)

# Write a single data file
gen(p, sigma, "data.json")
